pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract so it can send Ether
        vm.deal(address(c), 2 ether);
        // Owner sends 1 ether to a dummy address via sendMoney
        address dummy = address(0x1234);
        vm.prank(c.owner());
        c.sendMoney(dummy, 1 ether, "");
        // After sendMoney, the buggy contract's balance stays 2 ether because withdraw(0) transfers nothing
        // The reference contract's balance becomes 1 ether because withdraw(1 ether) transfers Ether out
        assertTrue(address(c).balance == 1 ether || address(c).balance == 2 ether, "balance mismatch");
        // The assertion passes on the reference (balance == 1 ether) and fails on the bug (balance == 2 ether)
    }
}

