        vm.deal(address(c), 10 ether);
        // Owner calls sendMoney to send 1 ether to a target
        address target = address(0x1234);
        vm.prank(owner);
        c.sendMoney(target, 1 ether, "");
        // After sendMoney, reference: contract.balance = 10 ether (sendMoney doesn't reduce contract balance)
        // Bug: withdrawAll will send 0 instead of 10 ether, so contract.balance stays 10 ether after withdrawAll
        c.withdrawAll();
        // Reference: all balance withdrawn to owner => address(c).balance == 0
        // Bug: only 0 withdrawn => address(c).balance == 10 ether
        assertTrue(address(c).balance == 0);
    }
}

