pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner sends 1 ether to a random address via sendMoney, so contract balance becomes 1 ether
        address target = address(0x1234);
        vm.deal(address(c), 1 ether); // Ensure contract has enough to send (but actually we can just deal directly)
        // Actually, let owner send 1 ether to target via sendMoney: owner is msg.sender, contract needs ether first
        // We'll deal ether to the contract first, then owner calls sendMoney
        vm.deal(address(c), 1 ether);
        vm.prank(c.owner());
        c.sendMoney(target, 1 ether, "");
        // Now contract balance should be 0? No, it sent 1 ether, so balance is 0. We need contract to have 1 ether before withdrawAll.
        // Better approach: send ether directly to contract via fallback, then withdrawAll
        vm.deal(address(this), 1 ether);
        payable(address(c)).call{value: 1 ether}("");
        // Now contract balance is 1 ether
        vm.prank(c.owner());
        c.withdrawAll();
        // Reference: balance becomes 0. Bug: call fails silently, balance stays 1 ether.
        assert(address(c).balance == 0);
    }
}

