import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the owner (which is the test contract itself, since new C() sets owner = msg.sender)
        vm.deal(address(this), 10 ether);
        // Send 1 ether to the contract via sendMoney, but with a target that will reject ether (address(this) which has no receive/fallback)
        // Actually owner = address(this) because setUp() deploys C, so msg.sender = address(this). We need the contract to have ether.
        // Better: use a different approach: make sendMoney send to a contract that rejects ether.
        // Deploy a simple rejector first.
        Rejector rejector = new Rejector();
        // Owner (address(this)) sends 1 ether to rejector via sendMoney; the call will revert, but the contract still receives ether? No, sendMoney sends to target, not to contract.
        // Let's think again: We want the contract to have 1 ether after sendMoney, then withdrawAll should send it to owner.
        // We can just use fallback to receive ether.
        // Send 1 ether directly to contract via fallback: c.fall{value: 1 ether}() via owner prank.
        vm.deal(address(this), 10 ether);
        vm.prank(address(this));
        (bool ok, ) = address(c).call{value: 1 ether}("");
        require(ok, "fund failed");
        // Now contract has 1 ether. Owner calls withdrawAll.
        vm.prank(address(this));
        c.withdrawAll();
        // Reference: all ether transferred, address(c).balance == 0.
        // Buggy: withdraw call reverts (because msg.sender = address(this) has no receive/fallback? Actually address(this) is a contract, it does have receive/fallback by default from Test). Let's ensure it rejects.
        // Actually Test contract has receive() external payable? No, forge-std Test does not define receive/fallback by default. But we can make it reject by not having a receive function. However, we are calling withdrawAll from address(this), which is the test contract. It does have a default fallback? In Solidity, a contract without receive/fallback will reject ether transfers via call. However, the test contract in Foundry does inherit from Test, which has no receive/fallback. So the call will revert and buggy code will not revert (it swallows the return), leaving ether. But the reference's transfer will revert? transfer reverts on failure. So reference's withdrawAll will revert. That's not right.
        // We need the receiver to accept ether for reference and reject for bug? Actually the difference is that reference uses transfer (which reverts on failure) and bug uses call without checking (silent fail). So we need the receiver to reject the ether so that the reference reverts (we don't want that) or the bug doesn't revert? Let's redesign: We want the reference to succeed (transfer all ether) and the bug to fail (leave ether). For that, the receiver must accept ether. So the owner must be an EOA or a contract that accepts ether. But we are the test contract, which can accept ether if we define receive() external payable. Let's add that.
        // We'll modify to have an explicit receiver contract that always accepts ether.
    }
}

